'use strict';
const $=(q,r=document)=>r.querySelector(q), $$=(q,r=document)=>[...r.querySelectorAll(q)];
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5Z"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-4"/>',chart:'<path d="M4 3v18h17M9 16v-5m5 5V7m5 9v-7"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4h8v3M3 12a24 24 0 0 0 18 0M10 13h4"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0"/><circle cx="12" cy="20" r=".7"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5m0 3v.1"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',arrow:'<path d="M4 12h15m-5-5 5 5-5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',book:'<path d="M12 5v16M3 4c4-1 6 0 9 2 3-2 5-3 9-2v15c-4-1-6 0-9 2-3-2-5-3-9-2Z"/>',flame:'<path d="M13 2c1 6 6 7 6 13a7 7 0 0 1-14 0c0-4 3-7 4-8 0 3 1 4 2 4 2-2 3-5 2-9Z"/>',award:'<circle cx="12" cy="9" r="6"/><path d="m8 14-2 8 6-3 6 3-2-8"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18m-13 4h2m4 0h2"/>',check:'<path d="m5 12 4 4L20 5"/>',leaf:'<path d="M20 3C9 2 3 7 5 15c7 5 15-1 15-12ZM4 21 15 10"/>',monitor:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 22h8m-4-5v5"/>',bolt:'<path d="m13 2-9 12h7l-1 8 10-12h-7Z"/>',heart:'<path d="M20 5a5 5 0 0 0-8 1 5 5 0 0 0-8 6l8 9 8-9a5 5 0 0 0 0-7Z"/>'};
function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" aria-hidden="true">${icons[n]||icons.book}</svg>`}function hydrate(){ $$('[data-icon]').forEach(x=>x.innerHTML=icon(x.dataset.icon)); }
function esc(t){return String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
let storageOK=true;let state;try{state=JSON.parse(localStorage.getItem('nunya-state'))||{}}catch{storageOK=false;state={}}
state={profile:{name:'',school:'Seconde',level:'beginner',goal:15},done:[],downloads:[],activity:{},minutes:0,lang:'fr',lowData:true,lastCourse:'python',...state};state.profile={name:'',school:'Seconde',level:'beginner',goal:15,...state.profile};
function persist(){try{localStorage.setItem('nunya-state',JSON.stringify(state));return true}catch{storageOK=false;toast('Le stockage de cet appareil est indisponible. Exporte ta progression pour la conserver.');return false}}
let page='home', filter='all', activeCourse=null,activeLesson=0,quizSelection=null,toastTimer,previousFocus,swReady=false;
const EN={myspace:'MY SPACE',dashboard:'Dashboard',explore:'Explore learning paths',downloads:'My downloads',progress:'My progress',careers:'Careers & guidance',everywhere:'Learn, even without a network.',offlinedesc:'Download your lessons and take your future with you.',discover:'Discover offline learning',help:'Need a little help?',myjourney:'My learning',search:'Find a course',footer:'A future to learn, together.',prototype:'TIA project · Pilot edition',about:'About Nunya ↗'};
const FR={};$$('[data-i]').forEach(e=>FR[e.dataset.i]=e.textContent);
const tr=(f,e)=>state.lang==='en'?e:f;
const lesson=(title,body,code,output,question,options,answer,explanation)=>({title,body,code,output,question,options,answer,explanation});
const courses=[
{id:'python',title:'Premiers pas avec Python',en:'First steps with Python',category:'PROGRAMMATION',desc:'De ta première ligne de code à tes premières idées qui prennent vie.',enDesc:'From your first line of code to bringing your own ideas to life.',type:'python',level:'Débutant',duration:80,lessons:[
lesson('Bonjour, le monde !','Un programme est une suite d’instructions que l’ordinateur suit dans l’ordre. En Python, la fonction print() affiche un message. Le texte doit être placé entre guillemets. Lis cet exemple, puis essaie de prévoir son résultat.','print("Bonjour, le Togo !")','Bonjour, le Togo !','Quelle instruction affiche le mot Nunya ?',['print("Nunya")','print(Nunya)','affiche("Nunya")'],0,'print("Nunya") affiche le texte entre guillemets. Sans guillemets, Python cherche une variable appelée Nunya.'),
lesson('Les variables : des petites boîtes','Une variable permet de garder une valeur en mémoire. Choisis un nom clair, puis utilise le signe = pour lui donner une valeur. Ici, age est un nombre et prenom est du texte. Tu peux changer la valeur d’une variable plus tard.','prenom = "Ama"\nage = 16\nprint(prenom)\nprint(age + 1)','Ama\n17','Après score = 3 puis score = score + 2, que vaut score ?',['3','5','32'],1,'score contient d’abord 3. On ajoute 2, puis on range le résultat 5 dans la même variable.'),
lesson('Calculer avec Python','Python peut servir de calculatrice : + additionne, - soustrait, * multiplie et / divise. Les parenthèses indiquent les calculs à faire en premier. Exemple : trois cahiers à 250 FCFA chacun.','prix = 250\nquantite = 3\ntotal = prix * quantite\nprint(total)','750','Que donne (2 + 3) * 4 ?',['14','20','24'],1,'Les parenthèses passent en premier : 2 + 3 = 5, puis 5 × 4 = 20.'),
lesson('Faire des choix avec if','Une condition permet au programme de choisir une action. if veut dire « si » et else veut dire « sinon ». Le symbole >= signifie « supérieur ou égal ». Les espaces au début des lignes sont importants en Python : ils indiquent ce qui appartient à chaque bloc.','note = 14\nif note >= 10:\n    print("Bravo !")\nelse:\n    print("On continue à apprendre.")','Bravo !','Avec note = 8, quel message s’affiche ?',['Bravo !','On continue à apprendre.','Aucun message'],1,'8 est inférieur à 10. La condition est fausse, donc le bloc else est exécuté.'),
lesson('Répéter avec une boucle','Une boucle répète une instruction. for nombre in range(3) fait prendre à nombre les valeurs 0, 1 et 2. La limite finale, 3, n’est pas incluse. Une boucle évite de recopier les mêmes instructions.','for nombre in range(3):\n    print("Je progresse !")','Je progresse !\nJe progresse !\nJe progresse !','Combien de fois range(4) fait-il répéter la boucle ?',['3 fois','4 fois','5 fois'],1,'range(4) produit 0, 1, 2, 3 : quatre valeurs, donc quatre répétitions.'),
lesson('Rassembler des données','Une liste rassemble plusieurs valeurs entre crochets. On accède à chaque élément avec son indice. Attention : le premier indice est 0 ! len() donne le nombre d’éléments de la liste.','villes = ["Lomé", "Kara", "Sokodé"]\nprint(villes[0])\nprint(len(villes))','Lomé\n3','Quelle expression donne Kara ?',['villes[0]','villes[1]','villes[2]'],1,'Les indices commencent à 0 : Lomé est à l’indice 0 et Kara à l’indice 1.'),
lesson('Créer une fonction','Une fonction regroupe des instructions que l’on peut réutiliser. def crée la fonction ; son nom permet de l’appeler. Un paramètre, comme prenom, lui permet de travailler avec différentes données.','def saluer(prenom):\n    return "Bonjour " + prenom\n\nprint(saluer("Kossi"))','Bonjour Kossi','Quel mot-clé renvoie le résultat d’une fonction ?',['print','return','for'],1,'return transmet une valeur au code qui a appelé la fonction. print affiche une valeur à l’écran.'),
lesson('Ton mini-projet : un budget','Tu connais maintenant les variables, les calculs, les conditions, les boucles, les listes et les fonctions. Relie ces notions dans un premier projet : calculer un budget de transport hebdomadaire. Sur papier, adapte le prix et le nombre de jours à ton quotidien.','def budget_semaine(prix_jour, jours):\n    return prix_jour * jours\n\ntotal = budget_semaine(500, 5)\nprint(total)','2500','Avec 300 FCFA par jour pendant 4 jours, quel est le total ?',['700 FCFA','1 200 FCFA','1 500 FCFA'],1,'300 × 4 = 1 200 FCFA. Tu viens d’utiliser une logique de programmation pour résoudre un problème concret !')
]},
{id:'web',title:'Crée ta première page web',en:'Build your first web page',category:'DÉVELOPPEMENT WEB',desc:'Du HTML au JavaScript : donne une place à tes idées sur le web.',enDesc:'From HTML to JavaScript: give your ideas a home on the web.',type:'web',level:'Débutant',duration:60,lessons:[
lesson('Le web, comment ça marche ?','Un navigateur affiche des pages web. HTML décrit le contenu, CSS définit l’apparence, et JavaScript ajoute de l’interactivité. Une page peut aussi être un fichier local : elle n’a pas toujours besoin d’Internet pour s’ouvrir.','HTML → le contenu\nCSS → le style\nJavaScript → les interactions','Une page structurée, stylée et interactive.','Quel langage décrit la structure du contenu ?',['CSS','HTML','Python'],1,'HTML est le langage de balisage qui structure les titres, paragraphes, liens et autres éléments.'),
lesson('Tes premières balises HTML','Une balise indique la nature d’un élément. <h1> est le titre principal et <p> un paragraphe. La plupart des balises s’ouvrent et se ferment. Le texte se place entre les deux.','<h1>Bienvenue à Lomé</h1>\n<p>Voici ma première page.</p>','Bienvenue à Lomé\nVoici ma première page.','Quelle balise sert à écrire un paragraphe ?',['<p>','<h1>','<img>'],0,'<p> définit un paragraphe. <h1> définit le titre principal et <img> insère une image.'),
lesson('Mettre des couleurs avec CSS','CSS associe un sélecteur à des propriétés. Le sélecteur h1 cible tous les titres h1. color change la couleur du texte, tandis que font-size change sa taille. Chaque déclaration se termine par un point-virgule.','h1 {\n  color: green;\n  font-size: 28px;\n}','Un titre vert, d’une taille de 28 pixels.','Quelle propriété change la couleur du texte ?',['background','font-size','color'],2,'color change la couleur du texte. background change le fond de l’élément.'),
lesson('Découvrir JavaScript','JavaScript permet à une page de réagir. const crée une variable dont on ne réaffecte pas la valeur. console.log() affiche une information dans la console du navigateur, utile pour vérifier ton programme.','const prenom = "Ama";\nconsole.log("Bonjour " + prenom);','Bonjour Ama','Que fait le signe + entre deux textes ?',['Il colle les textes ensemble','Il soustrait les textes','Il supprime la variable'],0,'Avec des chaînes de caractères, + concatène : il rassemble les textes en un seul.'),
lesson('Un bouton qui réagit','Le DOM est la représentation de la page que JavaScript peut modifier. querySelector sélectionne un élément. addEventListener attend un événement, comme un clic, puis exécute une fonction.','const bouton = document.querySelector("button");\nbouton.addEventListener("click", () => {\n  bouton.textContent = "Bravo !";\n});','Après un clic, le bouton affiche Bravo !','Quel événement correspond à un clic ?',['hover','click','load'],1,'click est déclenché lorsqu’on active le bouton avec la souris, le toucher ou le clavier.'),
lesson('Mini-projet : ta carte de présentation','Crée une page qui te présente : un titre avec ton prénom, un paragraphe sur ce que tu aimes apprendre, et un bouton. Écris d’abord le HTML sur papier. Ajoute un style lisible avec un contraste suffisant. Tu peux tester le fichier dans un navigateur quand tu as accès à un ordinateur.','<h1>Ama — apprentie développeuse</h1>\n<p>J’aime créer des choses utiles.</p>\n<button>Dire bonjour</button>','Une petite page de présentation personnelle.','Pour rendre une page plus accessible, que faut-il privilégier ?',['Un texte minuscule','Un contraste lisible et des titres clairs','Uniquement des images'],1,'Des titres structurés et un bon contraste aident plus de personnes à comprendre et utiliser ta page.')
]},
{id:'digital',title:'À l’aise avec le numérique',en:'Feel at home with digital tools',category:'CULTURE NUMÉRIQUE',desc:'Les bons réflexes pour explorer, comprendre et utiliser le numérique.',enDesc:'Practical skills to explore, understand and use digital tools.',type:'digital',level:'Tous niveaux',duration:60,lessons:[
lesson('Comprendre ton appareil','Un appareil comporte du matériel (écran, processeur, mémoire) et des logiciels (applications, système). Le stockage conserve les fichiers. La mémoire vive sert au travail en cours. Une application légère demande moins de ressources.','Matériel → ce que tu peux toucher\nLogiciel → les programmes\nStockage → les fichiers conservés','Un téléphone contient du matériel et des logiciels.','Où tes photos sont-elles conservées durablement ?',['Dans le stockage','Uniquement dans la mémoire vive','Dans le clavier'],0,'Le stockage garde les fichiers, y compris quand l’appareil est éteint.'),
lesson('Organiser tes fichiers','Donne à tes fichiers des noms faciles à retrouver et classe-les dans des dossiers. Une extension indique souvent le type : .pdf pour un document, .jpg pour une image, .py pour un programme Python. Faire une copie sur un autre support protège contre la perte de l’appareil.','Cours/\n  Python/\n    lecon-01.pdf\n  Projets/\n    budget.py','Une organisation qui t’aide à retrouver tes documents.','Quel nom est le plus facile à retrouver ?',['document-final-final2','cours-python-variables.pdf','truc'],1,'Un nom descriptif donne le sujet et le type de document sans devoir l’ouvrir.'),
lesson('Économiser ses données','Le texte consomme généralement moins de données que la vidéo. Télécharge les leçons lors d’une connexion disponible, puis utilise-les hors ligne. Sur Nunya, les leçons sont en texte : aucune vidéo ne démarre automatiquement.','1. Se connecter\n2. Ouvrir Mes téléchargements\n3. Enregistrer un parcours\n4. Revenir hors connexion','Tes cours restent sur cet appareil.','Quelle habitude économise généralement les données ?',['Lancer automatiquement les vidéos','Lire une leçon textuelle enregistrée','Télécharger plusieurs fois le même fichier'],1,'Une leçon textuelle enregistrée se lit sans nouvelle consommation de données.'),
lesson('Protéger ses comptes','Choisis une phrase de passe longue et unique pour chaque compte. Un gestionnaire de mots de passe peut aider à les conserver. Quand elle est disponible, active l’authentification à deux facteurs. Ne partage jamais un code de connexion reçu par message.','Phrase de passe → longue et unique\nDeuxième facteur → protection supplémentaire\nCode de connexion → à garder privé','Plusieurs protections valent mieux qu’une seule.','Un inconnu te demande ton code de connexion. Que fais-tu ?',['Je le lui envoie','Je le publie','Je ne le partage pas'],2,'Un code de connexion permet d’accéder à ton compte. Il doit rester privé, même si le message paraît urgent.'),
lesson('Vérifier une information','Avant de partager une information, cherche qui la publie, à quelle date et sur quelles preuves elle repose. Compare avec une autre source fiable. Un message très partagé peut quand même être faux. Une image peut être sortie de son contexte.','Qui publie ?\nQuelle date ?\nQuelles preuves ?\nUne autre source confirme-t-elle ?','Quatre questions pour prendre du recul.','Un message est très partagé. Cela prouve-t-il qu’il est vrai ?',['Oui, toujours','Non, il faut vérifier les sources','Oui, si le titre est convaincant'],1,'La popularité d’une publication ne prouve pas sa fiabilité. La source et les preuves sont plus utiles.'),
lesson('Créer avec responsabilité','Respecte le travail des autres : indique tes sources et vérifie les licences avant de réutiliser une image. Demande l’accord d’une personne avant de publier sa photo. Pour un premier projet scolaire, utilise tes propres textes et évite les informations personnelles.','Avant de publier :\n✓ Mes sources sont indiquées\n✓ J’ai le droit d’utiliser les images\n✓ Je respecte la vie privée','Un projet utile et respectueux des autres.','Avant de publier la photo d’un camarade, tu dois…',['Demander son accord','Ajouter un filtre','Publier vite'],0,'L’accord de la personne est essentiel. Respecter sa vie privée compte autant que la technique.')
]}
];
const getCourse=id=>courses.find(c=>c.id===id)||courses[0];const cname=c=>tr(c.title,c.en);const doneCount=c=>c.lessons.filter((_,i)=>state.done.includes(`${c.id}:${i}`)).length;const pct=c=>Math.round(doneCount(c)/c.lessons.length*100);const nextLesson=c=>{const n=c.lessons.findIndex((_,i)=>!state.done.includes(`${c.id}:${i}`));return n<0?0:n};
function totalDone(){return courses.reduce((s,c)=>s+doneCount(c),0)}function dayKey(d=new Date()){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function streak(){let n=0;let d=new Date();if(!state.activity[dayKey(d)])d.setDate(d.getDate()-1);while(state.activity[dayKey(d)]){n++;d.setDate(d.getDate()-1)}return n}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 400 280" fill="none" aria-hidden="true"><circle cx="213" cy="140" r="111" stroke="#d6e1ca" stroke-dasharray="4 6"/><circle cx="213" cy="140" r="87" fill="#e2ecd8"/><path d="M55 225h298" stroke="#c9d9bc"/><path d="m62 114 7 2m-3-6-1 11M328 62l9 3m-5-8-2 12" stroke="#b3c09e" stroke-width="2"/><circle cx="87" cy="57" r="4" fill="#cfba77"/><circle cx="342" cy="197" r="4" fill="#98b18c"/><g transform="rotate(-7 173 140)"><rect x="95" y="70" width="164" height="112" rx="9" fill="#c5d5b5"/><rect x="89" y="63" width="164" height="112" rx="9" fill="#fbfcf3" stroke="#b3c8a2"/><path d="M89 84h164" stroke="#d7e1cd"/><circle cx="101" cy="74" r="2" fill="#dba77f"/><circle cx="109" cy="74" r="2" fill="#d8ca8e"/><circle cx="117" cy="74" r="2" fill="#acc198"/><text x="107" y="106" fill="#97a78a" font-family="monospace" font-size="8">mon_premier_programme.py</text><text x="108" y="128" fill="#699452" font-family="monospace" font-size="10">print(<tspan fill="#bb8e58">"Bonjour, le Togo !"</tspan>)</text><text x="108" y="148" fill="#9aa78e" font-family="monospace" font-size="8">&gt; Le début d’une belle aventure.</text></g><g transform="rotate(8 242 191)"><path d="M157 179q36-12 72 1v48q-36-13-72-1Z" fill="#fffaf0" stroke="#d1c4a3"/><path d="M229 180q36-13 72-1v48q-36-12-72 1Z" fill="#f7efd8" stroke="#d1c4a3"/><path d="M229 180v48m-61-36 47 2m-47 6 47 2m-47 6 34 1m39-16 47-2m-47 10 47-2m-47 10 33-1" stroke="#d6cbaa"/></g><rect x="271" y="100" width="56" height="56" rx="13" transform="rotate(12 271 100)" fill="#427250"/><text x="280" y="137" fill="#e6eedb" font-family="monospace" font-size="23" transform="rotate(12 285 120)">&lt;/&gt;</text><path d="M105 225v-46" stroke="#7c9e66" stroke-width="3"/><path d="M105 201q-26-1-24-24 26 0 24 24" fill="#a5bd8c"/><path d="M105 191q1-27 24-27 2 26-24 27" fill="#7e9d66"/><path d="M89 213h32l-5 18H94Z" fill="#cda27d"/><circle cx="307" cy="51" r="16" fill="#f9f5e6" stroke="#dfd9b8"/><path d="m300 51 5 5 9-11" stroke="#82975d" stroke-width="2"/><path d="m149 44 4 8 8 1-6 6 2 8-8-4-7 4 1-8-6-6 8-1Z" fill="#d7bb74"/></svg>`}
function art(c){if(c.type==='python')return '<div class="art-code">Py<span style="color:#a5b68e">_</span><small>print("Hello, world!")</small></div>';if(c.type==='web')return '<div class="browser-art"><div class="browser-dots"><i></i><i></i><i></i></div><b>&lt;/&gt;</b></div>';return `<div class="digital-art">${icon('monitor')}</div>`}
function courseCard(c){return `<article class="course-card ${c.type}"><div class="course-art ${c.type}"><span class="course-badge">${icon('download')} ${tr('Disponible hors ligne','Available offline')}</span>${art(c)}</div><div class="course-body"><span class="course-category">${tr(c.category,c.id==='web'?'WEB DEVELOPMENT':c.id==='python'?'PROGRAMMING':'DIGITAL SKILLS')}</span><h3>${cname(c)}</h3><p>${tr(c.desc,c.enDesc)}</p><div class="course-meta"><span>${icon('book')}${c.lessons.length} ${tr('leçons','lessons')}</span><span>${icon('clock')}${c.duration} min</span><span>${icon('chart')}${tr(c.level,'Beginner')}</span></div><div class="course-action-row"><button data-course="${c.id}">${tr(doneCount(c)?'Continuer':'Découvrir le parcours',doneCount(c)?'Continue':'Explore this path')} ${icon('arrow')}</button><button class="download-btn" data-download="${c.id}" aria-label="${state.downloads.includes(c.id)?'Parcours enregistré':'Enregistrer '+esc(c.title)}">${icon(state.downloads.includes(c.id)?'check':'download')}</button></div></div></article>`}
function stats(){return `<section class="stats-grid" aria-label="${tr('Mes statistiques','My statistics')}">${[['book',totalDone(),tr('leçons terminées','lessons completed'),''],['flame',streak(),tr('d’apprentissage consécutif','of learning in a row'),tr('jour'+(streak()>1?'s':''),'days')],['clock',state.minutes,tr('à construire ton avenir','spent building your future'),'min'],['award',[totalDone()>=1,totalDone()>=5,courses.some(c=>pct(c)===100)].filter(Boolean).length,tr('badges débloqués','badges unlocked'),'']].map(([i,n,l,u])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><div><strong>${n}<small>${u}</small></strong><p>${l}</p></div></div>`).join('')}</section>`}
function render(){document.documentElement.lang=state.lang;document.body.classList.toggle('low-data',state.lowData);$$('[data-i]').forEach(e=>e.textContent=state.lang==='en'?(EN[e.dataset.i]||FR[e.dataset.i]):FR[e.dataset.i]);$('#language-label').textContent=state.lang.toUpperCase();$('#profile-btn').textContent=(state.profile.name||'A').slice(0,1).toUpperCase();$$('.nav-item').forEach(e=>e.classList.toggle('active',e.dataset.page===page));$('#breadcrumb-current').textContent=tr(({home:'Tableau de bord',explore:'Explorer les parcours',downloads:'Mes téléchargements',progress:'Ma progression',careers:'Métiers & orientation'})[page],({home:'Dashboard',explore:'Learning paths',downloads:'My downloads',progress:'My progress',careers:'Careers & guidance'})[page]);const views={home:homeView,explore:exploreView,downloads:downloadsView,progress:progressView,careers:careersView};$('#main').innerHTML=(!navigator.onLine?`<div class="offline-warning">${tr('Tu es hors connexion. Tes parcours enregistrés et ta progression restent disponibles sur cet appareil.','You are offline. Saved courses and progress remain available on this device.')}</div>`:'')+views[page]();hydrate()}
function homeView(){const c=getCourse(state.lastCourse),n=nextLesson(c);const name=state.profile.name?`, ${esc(state.profile.name)}`:'';return `<section class="greeting-row"><div><h1>${tr('Bonjour','Hello')}${name} <span class="wave">☀️</span></h1><p>${tr('Content de te retrouver. Qu’est-ce qu’on apprend aujourd’hui ?','Good to see you. What shall we learn today?')}</p></div><div class="date-chip">${icon('calendar')}${new Date().toLocaleDateString(state.lang==='fr'?'fr-FR':'en-GB',{day:'numeric',month:'long',year:'numeric'})}</div></section><section class="hero"><div class="hero-content"><div class="eyebrow"><span class="dot"></span>${tr('TON AVENIR COMMENCE ICI','YOUR FUTURE STARTS HERE')}</div><h2>${tr('Un petit pas aujourd’hui.<br>Un grand pas pour <em>demain.</em>','A small step today.<br>A big step for <em>tomorrow.</em>')}</h2><p>${tr('Découvre l’informatique, développe tes talents et construis ton chemin. À ton rythme, sans pression, même sans connexion.','Discover technology, build your skills and find your own path. At your pace, without pressure, even offline.')}</p><div class="hero-bottom"><button class="primary" data-action="hero">${tr(totalDone()?'Continuer mon apprentissage':'Trouver mon point de départ',totalDone()?'Continue learning':'Find my starting point')}${icon('arrow')}</button><small>${icon('check')}${tr('Gratuit. En français. Pour toi.','Free. French-first. Made for you.')}</small></div></div>${heroArt()}</section>${stats()}<div class="learning-layout"><section><div class="section-heading"><h2>${tr(totalDone()?'Reprendre là où tu en étais':'Ton premier pas',totalDone()?'Pick up where you left off':'Your first step')} <span class="count">${tr('MON PARCOURS','MY PATH')}</span></h2><button class="text-button" data-page="progress">${tr('Ma progression','My progress')}${icon('arrow')}</button></div><article class="resume-card"><div class="resume-art"><div class="code-icon">${c.id==='web'?'&lt;/&gt;':c.id==='digital'?'@':'Py'}</div></div><div class="resume-body"><span class="tag">${icon('leaf')}${tr(c.level,'Beginner')} · ${tr('À TON RYTHME','AT YOUR PACE')}</span><h3>${cname(c)}</h3><p>${tr('Leçon','Lesson')} ${n+1} : ${esc(c.lessons[n].title)}</p><div class="progress-line"><span style="width:${pct(c)}%"></span></div><div class="resume-meta"><span>${doneCount(c)} ${tr('sur','of')} ${c.lessons.length} ${tr('leçons terminées','lessons complete')}</span><button data-course="${c.id}">${tr(totalDone()?'Reprendre':'Commencer',totalDone()?'Resume':'Start')}${icon('arrow')}</button></div></div></article></section><section><div class="section-heading"><h2>${tr('Un peu chaque jour','A little, every day')} <span>✧</span></h2></div><article class="daily-card"><div class="daily-top"><span>${tr('LE DÉFI DU JOUR','TODAY’S CHALLENGE')}</span>${icon('bolt')}</div><h3>${tr('Et si tu pensais comme un dev ?','Think like a developer')}</h3><p>${tr('Un petit défi, une grande idée.<br>2 minutes pour faire travailler ta logique.','A small challenge, a big idea.<br>Give your logic a 2-minute workout.')}</p><button data-action="challenge">${tr('Relever le défi','Take the challenge')}${icon('arrow')}</button></article></section></div><section class="recommended"><div class="section-heading"><h2>${tr('Des chemins à explorer','Paths to explore')}</h2><button class="text-button" data-page="explore">${tr('Tous les parcours','All learning paths')}${icon('arrow')}</button></div><div class="course-grid">${courses.map(courseCard).join('')}</div></section><div class="hero-end-note">${icon('heart')}<span>${tr('<strong>Pas besoin de tout savoir pour commencer.</strong> Juste d’être curieux. Le reste, on l’apprend ensemble.','<strong>You don’t need to know everything to begin.</strong> Just be curious. We’ll learn the rest together.')}</span></div><div style="display:flex;justify-content:space-between;align-items:center;margin-top:17px"><span class="connection-indicator"><i></i>${tr('Version pilote · ton avis nous aide à grandir','Pilot edition · your feedback helps us grow')}</span><button class="text-button" data-action="feedback">${tr('Donner mon avis','Share feedback')} ↗</button></div>`}
function exploreView(){const list=filter==='all'?courses:courses.filter(c=>c.id===filter);return `<h1 class="page-title">${tr('À chaque curiosité, son chemin.','A path for every curiosity.')}</h1><p class="page-subtitle">${tr('Des bases solides, des petites victoires. Choisis un parcours et avance à ton rythme.','Strong foundations, small wins. Choose a path and learn at your own pace.')}</p><div class="filter-bar">${[['all','Tous les parcours','All paths'],['python','Python','Python'],['web','Développement web','Web development'],['digital','Culture numérique','Digital skills']].map(([id,f,e])=>`<button class="filter-chip ${filter===id?'selected':''}" data-filter="${id}">${tr(f,e)}</button>`).join('')}</div><div class="course-grid explore-grid">${list.map(courseCard).join('')}</div><div class="info-banner">${icon('compass')}<div><strong>${tr('Tu ne sais pas par où commencer ?','Not sure where to start?')}</strong><p>${tr('Personnalise ton profil : ta classe, ton expérience et le temps dont tu disposes nous aident à te proposer un point de départ.','Tell us your school level, experience and available time to get a starting point.')}</p><button class="text-button" style="margin-top:12px" data-action="profile">${tr('Trouver mon parcours','Find my path')} →</button></div></div><div class="resource-links"><span style="font-size:10px;color:var(--muted)">${tr('Pour aller plus loin (connexion requise) :','More resources (internet required):')}</span><a href="https://docs.python.org/fr/3/tutorial/" target="_blank" rel="noopener">Tutoriel Python ↗</a><a href="https://developer.mozilla.org/fr/docs/Learn_web_development" target="_blank" rel="noopener">MDN Web Docs ↗</a><a href="https://fr.khanacademy.org/computing" target="_blank" rel="noopener">Khan Academy ↗</a></div>`}
function downloadsView(){return `<h1 class="page-title">${tr('Ton savoir, partout avec toi.','Your knowledge, wherever you go.')}</h1><p class="page-subtitle">${tr('Enregistre un parcours quand tu as du réseau. Retrouve ses leçons et ses quiz sans connexion, sur ce même appareil.','Save a path when you’re connected. Read its lessons and take its quizzes offline, on this same device.')}</p><div class="info-banner">${icon('wifi')}<div><strong>${swReady?tr('Mode hors ligne prêt sur cet appareil','Offline mode ready on this device'):tr('Préparation du mode hors ligne','Preparing offline mode')}</strong><p>${tr('Ouvre le site une première fois en ligne, puis enregistre un parcours. Garde les données du navigateur : les effacer supprime aussi tes parcours et ta progression. Sur iPhone, tu peux ajouter Nunya à l’écran d’accueil depuis le menu Partager de Safari.','Open the site online first, then save a path. Keep your browser data: clearing it also removes your paths and progress. On iPhone, add Nunya to the Home Screen from Safari’s Share menu.')}</p></div></div><div class="download-list">${state.downloads.length?state.downloads.filter(id=>courses.some(c=>c.id===id)).map(id=>{const c=getCourse(id);return `<article class="download-row"><div><h3>${cname(c)}</h3><p>${iconInlineCheck()} ${c.lessons.length} ${tr('leçons et quiz · enregistré sur cet appareil','lessons and quizzes · saved on this device')} · ${Math.max(1,Math.ceil(new Blob([JSON.stringify(c)]).size/1024))} Ko</p></div><div style="display:flex;gap:9px"><button class="secondary" data-course="${c.id}">${tr('Ouvrir','Open')} →</button><button class="secondary danger" data-remove="${c.id}" aria-label="${tr('Retirer','Remove')} ${esc(cname(c))}">×</button></div></article>`}).join(''):`<div class="empty-state"><div class="empty-icon">${icon('download')}</div><h3>${tr('Un sac à dos encore léger.','Your backpack is still empty.')}</h3><p>${tr('Enregistre ton premier parcours. Pas de vidéo lourde : seulement l’essentiel pour comprendre et pratiquer.','Save your first path. No heavy videos: just what you need to understand and practise.')}</p><button class="primary" data-download="python">${tr('Enregistrer le parcours Python','Save the Python path')}${icon('download')}</button></div>`}</div><div class="settings-card"><div><h3>${tr('Mode économie de données','Data saving mode')}</h3><p>${tr('Privilégie tes parcours enregistrés et limite les éléments décoratifs. Les ressources externes ne se chargent que si tu ouvres leurs liens.','Prioritise saved paths and reduce decorative visuals. External resources load only when you open their links.')}</p></div><button class="toggle ${state.lowData?'on':''}" role="switch" aria-checked="${state.lowData}" aria-label="Mode économie de données" data-action="lowdata"></button></div>${state.downloads.length?`<div style="margin-top:22px"><button class="secondary" data-page="explore">${tr('Enregistrer un autre parcours','Save another path')} ${icon('arrow')}</button></div>`:''}`}
function iconInlineCheck(){return '<span style="color:#7c9c68">✓</span>'}
function progressView(){const today=state.activity[dayKey()]||0;return `<h1 class="page-title">${tr('Chaque petit pas compte.','Every small step counts.')}</h1><p class="page-subtitle">${tr('Ta progression t’appartient. Avance sans classement, sans comparaison et sans pression.','Your progress is yours. Learn without rankings, comparison or pressure.')}</p>${stats()}<div class="progress-cards"><section class="panel"><h3>${tr('Tes parcours','Your learning paths')}</h3>${courses.filter(c=>c.id!=='python').map(c=>`<div class="progress-entry"><div><span>${cname(c)}</span><span>${pct(c)} %</span></div><div class="progress-line"><span style="width:${pct(c)}%"></span></div><div class="progress-row-details"><span>${doneCount(c)} / ${c.lessons.length} ${tr('leçons','lessons')}</span><button class="text-button" data-course="${c.id}">${tr('Continuer','Continue')} →</button></div></div>`).join('')}</section><section class="panel"><h3>${tr('Ton rendez-vous avec toi-même','Your daily learning moment')}</h3><p style="font-size:12px;color:var(--muted)">${tr('Objectif quotidien','Daily goal')} : ${state.profile.goal} minutes</p><div class="progress-line" style="height:8px"><span style="width:${Math.min(100,today/state.profile.goal*100)}%"></span></div><p style="font-size:10px;color:var(--muted)">${today} / ${state.profile.goal} ${tr('minutes aujourd’hui','minutes today')}</p><button class="secondary" data-action="profile">${tr('Adapter mon objectif','Adjust my goal')}</button><p style="font-size:9px;color:#a1ab97">${tr('Temps indicatif : 10 minutes par nouvelle leçon validée.','Estimated time: 10 minutes for each new lesson completed.')}</p></section><section class="panel" style="grid-column:1/-1"><h3>${tr('Tes petites victoires','Your small victories')}</h3><div class="badge-list">${[['🌱','Premier pas','First step',1,totalDone()>=1],['✨','La curiosité grandit','Growing curiosity',5,totalDone()>=5],['🏅','Un chemin parcouru','A path completed',0,courses.some(c=>pct(c)===100)]].map(([e,f,en,n,earned])=>`<div class="achievement ${earned?'earned':''}"><span>${e}</span><strong>${tr(f,en)}</strong><small>${tr(earned?'Débloqué':n?n+' leçon'+(n>1?'s':''):'1 parcours terminé',earned?'Unlocked':n?n+' lessons':'Complete 1 path')}</small></div>`).join('')}</div></section></div><div class="settings-card"><div><h3>${tr('Garde une copie de tes progrès','Keep a copy of your progress')}</h3><p>${tr('Exporte une sauvegarde pour la conserver ou la restaurer sur un autre appareil. Aucun compte n’est nécessaire.','Export a backup to keep or restore on another device. No account is needed.')}</p></div><div style="display:flex;gap:7px;flex-wrap:wrap"><button class="secondary" data-action="export">${tr('Exporter','Export')}</button><button class="secondary" data-action="import">${tr('Restaurer','Restore')}</button></div></div>`}
function careersView(){return `<h1 class="page-title">${tr('Apprendre pour ouvrir des possibles.','Learn to open new possibilities.')}</h1><p class="page-subtitle">${tr('Explore des idées de métiers et les compétences qui les accompagnent. Commence par découvrir ce qui t’intéresse.','Explore career ideas and the skills they involve. Start by discovering what interests you.')}</p><div class="career-grid">${[['💻','Développeur / développeuse','Software developer','Créer des sites et des applications utiles, résoudre des problèmes et travailler en équipe.','Build useful websites and apps, solve problems, and collaborate.','Disponible : initiation','Available: introduction','tech'],['🩺','Médecin & métiers de la santé','Medicine & health careers','Découvrir les métiers du soin, leurs études et le rôle du numérique dans la santé.','Discover health professions, education pathways and digital tools in healthcare.','À construire avec des professionnels','To develop with professionals','health'],['🤝','Infirmier / infirmière','Nursing','Comprendre un métier au service des autres et les parcours d’études qui y préparent.','Learn about a career caring for others and the education that prepares you.','Phase future','Future phase','nursing'],['🌾','Agriculture & innovation','Agriculture & innovation','Explorer comment les outils numériques peuvent accompagner des projets agricoles.','Explore how digital tools can support agricultural projects.','Phase future','Future phase','agri'],['⚡','Énergie & métiers techniques','Energy & technical careers','Découvrir la maintenance, l’électricité et les bases d’un projet technique.','Discover maintenance, electricity and the foundations of technical projects.','Phase future','Future phase','energy'],['🎨','Design & entrepreneuriat','Design & entrepreneurship','Donner forme à une idée, comprendre un besoin et imaginer un service utile.','Shape an idea, understand a need, and imagine a useful service.','Phase future','Future phase','design']].map(([emoji,f,en,desc,ed,tag,et,id])=>`<article class="career-card"><div class="career-emoji">${emoji}</div><h3>${tr(f,en)}</h3><p>${tr(desc,ed)}</p><span class="career-tag">${tr(tag,et)}</span><div style="margin-top:17px"><button class="text-button" ${id==='tech'?'data-page="explore"':`data-interest="${id}"`}>${id==='tech'?tr('Découvrir les bases','Explore the basics'):tr('Ce domaine m’intéresse','I’m interested')} →</button></div></article>`).join('')}</div><div class="info-banner">${icon('compass')}<div><strong>${tr('Une initiation, pas un diplôme.','An introduction, not a qualification.')}</strong><p>${tr('Nunya t’aide à découvrir un domaine. Les autres secteurs seront développés après l’informatique, avec des enseignants et des professionnels au Togo. Les formations réglementées restent indispensables pour les métiers de la santé. Aucune offre d’emploi ni prévision de recrutement n’est publiée dans ce pilote.','Nunya helps you explore a field. Other sectors will follow technology, developed with educators and professionals in Togo. Health careers require formal training. This pilot does not publish job offers or recruitment forecasts.')}</p></div></div>`}
function navigate(p){page=p;$('#sidebar').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'})}
function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200)}
function modal(content,wide=false){if($('#modal').hidden)previousFocus=document.activeElement;$('#modal-content').innerHTML=content;$('.modal').classList.toggle('wide',wide);$('#modal').hidden=false;document.body.style.overflow='hidden';$('.workspace').inert=true;$('#sidebar').inert=true;$('#close-modal').focus();hydrate()}
function closeModal(){$('#modal').hidden=true;document.body.style.overflow='';$('.workspace').inert=false;$('#sidebar').inert=false;if(previousFocus?.isConnected)previousFocus.focus()}
function profileModal(){modal(`<div class="onboarding-art">✳</div><h2 id="modal-title">${tr('Ton parcours commence avec toi.','Your journey starts with you.')}</h2><p>${tr('Quelques repères pour t’accompagner. Pas de compte, pas de classement : juste toi et ton envie d’apprendre.','A few details to guide you. No account, no rankings: just you and your curiosity.')}</p><form id="profile-form"><label class="field">${tr('Comment veux-tu qu’on t’appelle ? (facultatif)','What should we call you? (optional)')}<input name="name" maxlength="30" placeholder="Ton prénom ou un pseudo" value="${esc(state.profile.name)}" autocomplete="nickname"></label><div class="two-fields"><label class="field">${tr('Ta classe','Your school level')}<select name="school">${['Seconde','Première','Terminale','Université'].map(x=>`<option ${state.profile.school===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">${tr('Ton expérience','Your experience')}<select name="level"><option value="beginner" ${state.profile.level==='beginner'?'selected':''}>${tr('Je découvre tout','Completely new')}</option><option value="some" ${state.profile.level==='some'?'selected':''}>${tr('J’ai déjà essayé de coder','I’ve tried coding')}</option><option value="comfortable" ${state.profile.level==='comfortable'?'selected':''}>${tr('Je connais les bases','I know the basics')}</option></select></label></div><label class="field">${tr('Un moment pour apprendre chaque jour','A little time to learn each day')}<select name="goal">${[10,15,30].map(x=>`<option value="${x}" ${Number(state.profile.goal)===x?'selected':''}>${x} minutes</option>`).join('')}</select></label><p class="form-note">${tr('Priorité aux lycéens ; les étudiants sont aussi les bienvenus. Les plus jeunes viendront dans une phase ultérieure. Ces informations restent dans ce navigateur.','Lycée students come first; university students are also welcome. Younger learners will be included in a later phase. These details stay in this browser.')}</p><button class="primary" type="submit">${tr('C’est parti !','Let’s begin!')}${icon('arrow')}</button></form>`)}
function openCourse(id,index){const c=getCourse(id);if(!navigator.onLine&&!state.downloads.includes(id)){toast(tr('Ce parcours n’est pas enregistré. Retrouve tes téléchargements pour apprendre hors ligne.','This path is not saved. Open your downloads to learn offline.'));navigate('downloads');return}activeCourse=c;activeLesson=index===undefined?nextLesson(c):index;state.lastCourse=c.id;persist();quizSelection=null;renderLesson()}
function renderLesson(){const c=activeCourse,l=c.lessons[activeLesson],completed=state.done.includes(`${c.id}:${activeLesson}`);modal(`<div class="lesson-label">${esc(cname(c))} · ${tr('LEÇON','LESSON')} ${activeLesson+1}/${c.lessons.length}</div><h2 id="modal-title">${esc(l.title)}</h2>${state.lang==='en'?'<p class="form-note">Pilot lesson content is in French. Full English lessons are planned; navigation and profiles are available in English.</p>':''}<div class="lesson-layout"><nav class="lesson-nav" aria-label="Leçons du parcours">${c.lessons.map((x,i)=>`<button data-lesson="${i}" class="${i===activeLesson?'current ':''}${state.done.includes(c.id+':'+i)?'complete':''}" ${i===activeLesson?'aria-current="step"':''}><span>${state.done.includes(c.id+':'+i)?'✓':String(i+1).padStart(2,'0')}</span>${esc(x.title)}</button>`).join('')}</nav><div class="lesson-content"><div class="tag">${icon('clock')} 10 MIN · ${tr('LIRE, COMPRENDRE, PRATIQUER','READ, UNDERSTAND, PRACTISE')}</div><p>${esc(l.body)}</p><pre><code>${esc(l.code)}</code></pre><p style="font-size:9px;margin-bottom:6px">${tr('Résultat de cet exemple','Example output')}</p><div class="example-output">${esc(l.output).replace(/\n/g,'<br>')}</div><section class="quiz-section"><span class="tag">${tr('À TOI DE JOUER','YOUR TURN')}</span><h3 style="font-size:14px;margin-top:10px">${esc(l.question)}</h3><div id="quiz-options">${l.options.map((o,i)=>`<button class="quiz-option" data-answer="${i}" aria-pressed="false">${String.fromCharCode(65+i)}. ${esc(o)}</button>`).join('')}</div><div id="quiz-feedback" aria-live="polite"></div><div class="modal-actions"><button class="primary" id="check-answer">${tr('Vérifier ma réponse','Check my answer')} ✓</button><button class="secondary" data-action="lesson-help">${tr('Un indice ?','Need a hint?')}</button></div>${completed?`<p class="form-note">✓ ${tr('Leçon déjà validée. Tu peux la revoir librement.','Lesson completed. Review it whenever you like.')}</p>`:''}</section></div></div>`,true)}
function verify(){if(quizSelection===null){toast(tr('Choisis d’abord une réponse.','Choose an answer first.'));return}const l=activeCourse.lessons[activeLesson];const right=quizSelection===l.answer;$$('.quiz-option').forEach((b,i)=>{b.classList.toggle('correct',right&&i===l.answer);b.classList.toggle('incorrect',!right&&i===quizSelection)});$('#quiz-feedback').innerHTML=`<div class="quiz-feedback ${right?'':'error'}"><strong>${right?tr('Bien joué !','Well done!'):tr('Tu y es presque.','You’re getting there.')}</strong> ${esc(right?l.explanation:'Relis l’exemple et essaie de suivre les instructions une par une. Tu peux réessayer autant de fois que tu veux.')}</div>`;if(right){const key=activeCourse.id+':'+activeLesson;if(!state.done.includes(key)){state.done.push(key);state.minutes+=10;state.activity[dayKey()]=(state.activity[dayKey()]||0)+10;persist();render()}$('#check-answer').outerHTML=`<button class="primary" id="next-lesson">${activeLesson<activeCourse.lessons.length-1?tr('Leçon suivante','Next lesson'):tr('Terminer le parcours','Finish this path')}${icon('arrow')}</button>`}}
async function saveDownload(id){if(!navigator.onLine){toast(tr('Reconnecte-toi pour enregistrer un nouveau parcours.','Connect to save a new path.'));return}if(state.downloads.includes(id)){toast(tr('Ce parcours est déjà enregistré.','This path is already saved.'));return}const btn=$(`[data-download="${id}"]`);if(btn){btn.disabled=true;btn.setAttribute('aria-busy','true')}try{if(!('serviceWorker'in navigator))throw Error('unsupported');await navigator.serviceWorker.register('./sw.js');const registration=await navigator.serviceWorker.ready;await new Promise((resolve,reject)=>{const ch=new MessageChannel();const timeout=setTimeout(()=>reject(Error('timeout')),15000);ch.port1.onmessage=e=>{clearTimeout(timeout);e.data.ok?resolve():reject(Error('cache'))};registration.active.postMessage({type:'CACHE_OFFLINE'},[ch.port2])});localStorage.setItem('nunya-pack-'+id,JSON.stringify(getCourse(id)));state.downloads.push(id);if(!persist())throw Error('storage');swReady=true;render();toast(tr('Parcours enregistré ! Tu peux maintenant le lire sans réseau.','Path saved! You can now read it offline.'));}catch(e){state.downloads=state.downloads.filter(x=>x!==id);try{localStorage.removeItem('nunya-pack-'+id);persist()}catch{}toast(tr('Enregistrement impossible. Vérifie ta connexion et l’espace disponible, puis réessaie.','Could not save. Check your connection and available storage, then try again.'));render()}finally{if(btn){btn.disabled=false;btn.removeAttribute('aria-busy')}}}
function searchModal(){modal(`<h2 id="modal-title">${tr('Qu’as-tu envie d’apprendre ?','What would you like to learn?')}</h2><label class="field">${tr('Chercher un parcours ou une leçon','Search paths and lessons')}<input id="course-search" type="search" placeholder="Python, variables, HTML…" autocomplete="off"></label><div class="search-results" id="search-results"></div>`);searchResults('');$('#course-search').focus()}
function searchResults(q){const query=q.toLocaleLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');const matches=[];for(const c of courses){if((c.title+' '+c.en+' '+c.category).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(query))matches.push({c,i:null,title:cname(c)});else c.lessons.forEach((l,i)=>{if((l.title+' '+l.body).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(query))matches.push({c,i,title:l.title})})}$('#search-results').innerHTML=matches.length?matches.slice(0,12).map(m=>`<button class="search-result" data-course="${m.c.id}" ${m.i!==null?`data-index="${m.i}"`:''}><span>${esc(m.title)}<br><small>${m.i===null?tr('Parcours complet','Complete path'):esc(cname(m.c))}</small></span>→</button>`).join(''):`<p>${tr('Aucun résultat. Essaie « Python », « HTML » ou « numérique ».','No results. Try “Python”, “HTML” or “digital”.')}</p>`}
function challengeModal(){modal(`<div class="lesson-label">${tr('LE DÉFI DU JOUR · 2 MINUTES','DAILY CHALLENGE · 2 MINUTES')}</div><h2 id="modal-title">${tr('Pense comme un développeur.','Think like a developer.')}</h2><p>${tr('Ama a 3 mangues. Elle en reçoit 2, puis en donne une à son ami. Quel nombre ce programme affiche-t-il ?','Ama has 3 mangoes. She receives 2, then gives one to a friend. What number does this program display?')}</p><pre class="challenge-code">mangues = 3\nmangues = mangues + 2\nmangues = mangues - 1\nprint(mangues)</pre><div class="filter-bar">${[3,4,5].map(n=>`<button class="secondary" data-challenge="${n}">${n}</button>`).join('')}</div><div id="challenge-feedback" aria-live="polite"></div>`)}
function helpModal(){modal(`<div class="onboarding-art">✳</div><h2 id="modal-title">${tr('On avance ensemble.','Let’s work through it together.')}</h2><p>${tr('Un guide local, disponible même hors ligne. Choisis ce qui te bloque : pas besoin de tout comprendre du premier coup.','An offline guide. Choose what you need help with: you don’t have to understand everything on the first try.')}</p><div class="help-topics"><button data-help="start">${tr('Je ne sais pas par où commencer','I don’t know where to start')}</button><button data-help="variables">${tr('Comprendre les variables','Understanding variables')}</button><button data-help="offline">${tr('Apprendre sans Internet','Learning without internet')}</button><button data-help="stuck">${tr('Je bloque sur un exercice','I’m stuck on an exercise')}</button></div><div id="helper-answer" aria-live="polite"></div><p class="form-note">${tr('Ce guide utilise des réponses préparées. L’assistant IA est prévu pour une version ultérieure.','This guide uses prepared answers. An AI assistant is planned for a later version.')}</p>`)}
const helpAnswers={start:['Commence par « À l’aise avec le numérique » si tu découvres les outils informatiques. Si tu sais déjà utiliser ton appareil, essaie Python. Une leçon à la fois suffit !','Start with digital skills if you’re new to computers. If you already feel comfortable with your device, try Python. One lesson at a time is enough.'],variables:['Imagine une boîte étiquetée « age ». L’instruction age = 16 y range 16. Puis age = age + 1 remplace 16 par 17. Le nom ne change pas, mais la valeur peut changer.','Imagine a box labelled “age”. age = 16 stores 16. age = age + 1 replaces 16 with 17. The label stays the same, but the value can change.'],offline:['Avec une connexion, ouvre « Mes téléchargements » et enregistre un parcours. Attends le message de confirmation. Ensuite, coupe le réseau et reviens sur la même adresse, dans le même navigateur. Ne supprime pas les données du site.','While connected, open My downloads and save a path. Wait for confirmation. Then turn off your connection and return to the same address in the same browser. Keep the site’s browser data.'],stuck:['Lis le code une ligne à la fois. Écris sur papier la valeur de chaque variable après chaque ligne. Compare avec les réponses proposées. Tu peux réessayer sans perdre de points : on apprend aussi avec ses erreurs.','Read one line at a time. Write down each variable’s value after each step. Compare your result with the answers. You can retry without losing points: mistakes are part of learning.']};
function feedbackModal(interest=''){modal(`<div class="lesson-label">${tr('CONSTRUISONS NUNYA ENSEMBLE','LET’S BUILD NUNYA TOGETHER')}</div><h2 id="modal-title">${tr('Ton avis change la suite.','Your feedback shapes what comes next.')}</h2><p>${tr('Ce pilote est fait pour être testé. Qu’est-ce qui t’aide ? Qu’est-ce qu’on peut améliorer ? Aucun nom ni contact n’est demandé.','This pilot is made for testing. What helps you? What could be better? No name or contact details are requested.')}</p><form id="feedback-form"><label class="field">${tr('Comment était ton expérience ?','How was your experience?')}<select name="rating" required><option value="">${tr('Choisir','Choose')}</option><option value="5">5 — Très facile à utiliser</option><option value="4">4 — Plutôt facile</option><option value="3">3 — Moyen</option><option value="2">2 — Plutôt difficile</option><option value="1">1 — Très difficile</option></select></label><label class="field">${tr('Ce qui t’aiderait le plus','What would help you most')}<select name="priority">${['Plus de leçons','Meilleur mode hors ligne','Plus d’exercices','Aide et explications','Métiers et orientation','Autre'].map(x=>`<option>${x}</option>`).join('')}</select></label><label class="field">${tr('Ton retour (sans information personnelle)','Your feedback (no personal details)')}<textarea name="message" required maxlength="2000" rows="4" style="width:100%;padding:12px;margin-top:7px;border:1px solid #dfe5d7;border-radius:6px;font:inherit;resize:vertical" placeholder="Ce que j’ai aimé, ce qui m’a bloqué…">${interest?esc('Le domaine '+interest+' m’intéresse. '):''}</textarea></label><p class="form-note">${tr('Ton avis est enregistré sur cet appareil. Exporte le fichier et remets-le à l’équipe du projet : il n’est pas transmis automatiquement.','Your feedback is saved on this device. Export the file and give it to the project team: it is not sent automatically.')}</p><div class="modal-actions"><button class="primary" type="submit">${tr('Enregistrer mon avis','Save my feedback')} ✓</button><button class="secondary" type="button" data-action="export-feedback">${tr('Exporter mes avis','Export my feedback')}</button></div></form>`)}
function downloadJSON(data,filename){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000)}
function exportProgress(){downloadJSON({format:'nunya-backup-v1',profile:state.profile,done:state.done,activity:state.activity,minutes:state.minutes,lang:state.lang},'nunya-progression-'+dayKey()+'.json');toast(tr('Sauvegarde exportée. Garde ce fichier dans un endroit sûr.','Backup exported. Keep this file somewhere safe.'))}
function importProgress(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>1000000)throw Error();const data=JSON.parse(await file.text());if(data.format!=='nunya-backup-v1'||!Array.isArray(data.done)||typeof data.profile!=='object'||!data.profile||!data.activity||typeof data.activity!=='object')throw Error();const validKeys=new Set(courses.flatMap(c=>c.lessons.map((_,i)=>c.id+':'+i)));state.done=[...new Set([...state.done,...data.done.filter(x=>validKeys.has(x))])];state.profile={name:typeof data.profile.name==='string'?data.profile.name.slice(0,30):'',school:['Seconde','Première','Terminale','Université'].includes(data.profile.school)?data.profile.school:'Seconde',level:['beginner','some','comfortable'].includes(data.profile.level)?data.profile.level:'beginner',goal:[10,15,30].includes(data.profile.goal)?data.profile.goal:15};if(data.notes&&typeof data.notes==='object'&&!Array.isArray(data.notes)){for(const [k,v] of Object.entries(data.notes)){if(validKeys.has(k)&&typeof v==='string')state.notes[k]=v.slice(0,2000)}}if(data.courseAccess&&typeof data.courseAccess==='object'){for(const c of courses)if(data.courseAccess[c.id]===true)state.courseAccess[c.id]=true}if(typeof data.followedPath==='string'&&typeof SECTORS!=='undefined'&&SECTORS.some(s=>s.jobs.some((_,i)=>s.id+':'+i===data.followedPath)))state.followedPath=data.followedPath;for(const field of ['resourceDone','resourceSaved'])if(Array.isArray(data[field]))state[field]=[...new Set([...(state[field]||[]),...data[field].filter(x=>typeof x==='string'&&/^(mdn-[a-f0-9]{16}|ka-[\w-]{11})$/.test(x))])];if(data.resourceNotes&&typeof data.resourceNotes==='object')for(const [k,v] of Object.entries(data.resourceNotes))if(/^(mdn-[a-f0-9]{16}|ka-[\w-]{11})$/.test(k)&&typeof v==='string')state.resourceNotes[k]=v.slice(0,2000);for(const field of ['mastery','reviewSchedule','errors'])if(data[field]&&typeof data[field]==='object'&&!Array.isArray(data[field]))for(const [k,v] of Object.entries(data[field]))if(validKeys.has(k)){if(field==='reviewSchedule'&&typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v))state[field][k]=v;else if(field==='mastery'&&v&&typeof v==='object'&&['tried','familiar','mastered'].includes(v.level))state[field][k]={level:v.level,attempts:Math.max(0,Math.min(100000,Number(v.attempts)||0)),successes:Math.max(0,Math.min(100000,Number(v.successes)||0))};else if(field==='errors'&&v&&typeof v.date==='string')state[field][k]={date:v.date.slice(0,10),course:k.split(':')[0]}}if(typeof data.accent==='string'&&/^#[a-fA-F0-9]{6}$/.test(data.accent))state.accent=data.accent.toLowerCase();if(['light','dark'].includes(data.theme))state.theme=data.theme;if(typeof data.readingFont==='boolean')state.readingFont=data.readingFont;if(typeof data.lowData==='boolean')state.lowData=data.lowData;if(typeof data.fontScale==='number'&&Number.isFinite(data.fontScale))state.fontScale=Math.max(.9,Math.min(1.3,data.fontScale));if(typeof data.profile.ageBand==='string')state.profile.ageBand=data.profile.ageBand.slice(0,30);if(typeof data.profile.series==='string')state.profile.series=data.profile.series.slice(0,30);if(typeof restoreAcademyData==='function')restoreAcademyData(data.academy);if(typeof restoreStudyProgress==='function')restoreStudyProgress(data.resourceWork);if(typeof restoreLocalProjects==='function')restoreLocalProjects(data.localProjects);if(['school','future','both'].includes(data.preferredTrack))state.preferredTrack=data.preferredTrack;state.minutes=totalDone()*10;for(const [k,v]of Object.entries(data.activity)){if(/^\d{4}-\d{2}-\d{2}$/.test(k)&&Number.isFinite(v)&&v>=0&&v<=10000)state.activity[k]=Math.max(state.activity[k]||0,v)}persist();render();toast(tr('Tes progrès ont été restaurés. Les parcours doivent être enregistrés à nouveau sur cet appareil.','Progress restored. Save your paths again on this device.'))}catch{toast(tr('Ce fichier n’est pas une sauvegarde Nunya valide.','This is not a valid Nunya backup.'))}};input.click()}
function aboutModal(){modal(`<div class="onboarding-art">✳</div><h2 id="modal-title">${tr('Le savoir ouvre des portes.','Knowledge opens doors.')}</h2><p>Nunya est un projet TIA à Colgate, imaginé pour rendre la découverte de l’informatique accessible aux jeunes au Togo. Cette édition s’adresse d’abord aux lycéens de la seconde à la terminale, puis aux étudiants. Les plus jeunes seront inclus dans une phase ultérieure.</p><p>76 leçons d’initiation, 17 parcours, 18 chemins métiers, des quiz et un mode hors ligne. Nunya permet d’explorer un domaine et ses premiers concepts ; il ne délivre ni diplôme ni qualification professionnelle.</p><p>Cette version pilote conserve les profils, les avis et les progrès sur l’appareil. Elle ne propose pas encore de comptes synchronisés, d’exécution de code ou d’assistant IA. Le contenu est à tester et à relire avec des enseignants avant une diffusion à grande échelle.</p><div class="modal-actions"><button class="primary" data-action="feedback">Donner mon avis →</button></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page){navigate(b.dataset.page);return}if(b.dataset.course){openCourse(b.dataset.course,b.dataset.index===undefined?undefined:Number(b.dataset.index));return}if(b.dataset.download){saveDownload(b.dataset.download);return}if(b.dataset.remove){state.downloads=state.downloads.filter(x=>x!==b.dataset.remove);try{localStorage.removeItem('nunya-pack-'+b.dataset.remove)}catch{}persist();render();toast(tr('Parcours retiré. Ta progression est conservée.','Path removed. Your progress is kept.'));return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.lesson!==undefined){activeLesson=Number(b.dataset.lesson);quizSelection=null;renderLesson();return}if(b.dataset.answer!==undefined){quizSelection=Number(b.dataset.answer);$$('.quiz-option').forEach((x,i)=>{x.classList.toggle('selected',i===quizSelection);x.classList.remove('incorrect','correct');x.setAttribute('aria-pressed',i===quizSelection?'true':'false')});$('#quiz-feedback').innerHTML='';return}if(b.id==='check-answer'){verify();return}if(b.id==='next-lesson'){if(activeLesson<activeCourse.lessons.length-1){activeLesson++;quizSelection=null;renderLesson()}else{modal(`<div class="onboarding-art">🌱</div><h2 id="modal-title">${tr('Un chemin parcouru. Et plein de possibles.','A path completed. So many possibilities ahead.')}</h2><p>${tr('Bravo pour cette étape ! Continue à pratiquer avec les exercices et explore un autre parcours quand tu le souhaites.','Well done on this step! Keep practising and explore another path when you’re ready.')}</p><button class="primary" data-action="finish">${tr('Voir ma progression','See my progress')} →</button>`)}return}if(b.dataset.challenge){const right=Number(b.dataset.challenge)===4;$('#challenge-feedback').innerHTML=`<div class="quiz-feedback ${right?'':'error'}">${right?tr('Bien joué ! 3 + 2 = 5, puis 5 − 1 = 4. Tu viens de suivre l’état d’une variable comme un développeur.','Well done! 3 + 2 = 5, then 5 − 1 = 4. You just tracked a variable like a developer.'):tr('Essaie encore : commence par 3, ajoute 2, puis enlève 1.','Try again: start with 3, add 2, then take away 1.')}</div>`;return}if(b.dataset.help){$('#helper-answer').innerHTML=`<div class="helper-answer">${tr(...helpAnswers[b.dataset.help])}</div>`;return}if(b.dataset.interest){feedbackModal(b.dataset.interest);return}const actions={hero:()=>{if(state.profileSet)openCourse(state.lastCourse);else profileModal()},profile:profileModal,challenge:challengeModal,lowdata:()=>{state.lowData=!state.lowData;persist();render()},'lesson-help':()=>{const l=activeCourse.lessons[activeLesson];$('#quiz-feedback').innerHTML=`<div class="quiz-feedback">${tr('Un indice : reprends l’exemple ci-dessus, puis lis chaque réponse en te demandant ce qu’elle ferait. Pour cette leçon :','Hint: review the example above, then consider what each answer would do. For this lesson:')} ${esc(l.body.split('. ')[0])}.</div>`},export:exportProgress,import:importProgress,finish:()=>{closeModal();navigate('progress')},feedback:()=>feedbackModal(),'export-feedback':()=>{if(!state.feedback?.length){toast(tr('Enregistre d’abord ton avis.','Save your feedback first.'));return}downloadJSON({format:'nunya-feedback-v1',feedback:state.feedback},'nunya-avis-'+dayKey()+'.json');toast(tr('Fichier exporté. Remets-le à l’équipe Nunya pour partager ton avis.','File exported. Give it to the Nunya team to share your feedback.'))}};if(b.dataset.action&&actions[b.dataset.action])actions[b.dataset.action]()});
document.addEventListener('submit',e=>{if(e.target.id==='profile-form'){e.preventDefault();const f=new FormData(e.target);state.profile={name:String(f.get('name')).trim().slice(0,30),school:String(f.get('school')),level:String(f.get('level')),goal:Number(f.get('goal'))};state.profileSet=true;state.lastCourse=state.profile.level==='beginner'?'digital':state.profile.level==='some'?'python':'web';persist();closeModal();render();toast(tr('Ton point de départ est prêt. Tu peux changer de parcours à tout moment.','Your starting point is ready. You can switch paths at any time.'))}if(e.target.id==='feedback-form'){e.preventDefault();const f=new FormData(e.target);state.feedback=state.feedback||[];state.feedback.push({date:new Date().toISOString(),rating:Number(f.get('rating')),priority:String(f.get('priority')),message:String(f.get('message')).trim().slice(0,2000)});if(persist()){modal(`<div class="onboarding-art">♡</div><h2 id="modal-title">${tr('Merci, ton avis compte.','Thank you. Your feedback matters.')}</h2><p>${tr('Ton retour est enregistré sur cet appareil. Pour le partager avec l’équipe du projet, exporte le fichier et remets-le-lui. Aucun envoi automatique n’a eu lieu.','Your feedback is saved on this device. To share it with the project team, export the file and give it to them. Nothing has been sent automatically.')}</p><button class="primary" data-action="export-feedback">${tr('Exporter mon avis','Export my feedback')} ${icon('download')}</button>`)}else toast(tr('Stockage indisponible. Exporte ton avis pour le conserver.','Storage unavailable. Export your feedback to keep it.'))}});
document.addEventListener('input',e=>{if(e.target.id==='course-search')searchResults(e.target.value)});
$('#close-modal').addEventListener('click',closeModal);$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});$('#profile-btn').onclick=profileModal;$('#help-btn').onclick=helpModal;$('#search-btn').onclick=searchModal;$('#about-btn').onclick=aboutModal;$('#menu-btn').onclick=()=>$('#sidebar').classList.toggle('open');$('#language-btn').onclick=()=>{state.lang=state.lang==='fr'?'en':'fr';persist();render();toast(tr('Interface en français.','English interface enabled. Pilot lessons remain in French.'))};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#sidebar').classList.remove('open')}if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();searchModal()}if(e.key==='Tab'&&!$('#modal').hidden){const f=$$('button:not(:disabled),input,select,textarea,a[href]',$('.modal')).filter(x=>x.getClientRects().length);const first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('online',()=>{render();toast(tr('Connexion retrouvée.','You’re back online.'))});window.addEventListener('offline',()=>{render();toast(tr('Hors connexion. Tes parcours enregistrés restent disponibles.','Offline. Your saved paths are still available.'))});
render();
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{swReady=true;if(page==='downloads')render()}).catch(()=>{swReady=false})}
